package paperwork

import (
 "context"
 "database/sql"
 "errors"
 "fmt"
 "net/url"
 "regexp"
 "strconv"
 "strings"
)
var printedTask=regexp.MustCompile(`^T\d{5,}$`)
func(s *Store)EnsureLocal(p Proposal)(map[string]string,error){if len(p.Review)>0{return nil,errors.New("Resolve review entries first")};result:=map[string]string{};for _,b:=range p.Blocks{first:=firstWord(b.Text)
 if b.Kind=="task-update" {var block string;if e:=s.DB.QueryRow("SELECT block_id FROM tasks WHERE task_id=?",first).Scan(&block);e!=nil{if e==sql.ErrNoRows{return nil,errors.New("Unknown task update ID: "+first)};return nil,e};tx,e:=s.DB.Begin();if e!=nil{return nil,e};if _,e=tx.Exec("UPDATE task_data SET done=1 WHERE block_id=?",block);e==nil{_,e=tx.Exec("UPDATE tasks SET phase='pending-update' WHERE task_id=?",first)};if e==nil{_,e=tx.Exec("INSERT OR IGNORE INTO task_mentions VALUES (?,?)",b.ID,first)};if e!=nil{tx.Rollback();return nil,e};if e=tx.Commit();e!=nil{return nil,e};continue}
 if b.Kind!="task"{continue};var mentioned string;e:=s.DB.QueryRow("SELECT task_id FROM tasks WHERE task_id=?",first).Scan(&mentioned);if e==nil{result[b.ID]=mentioned;if _,e=s.DB.Exec("INSERT OR IGNORE INTO task_mentions VALUES (?,?)",b.ID,mentioned);e!=nil{return nil,e};continue};if e!=sql.ErrNoRows{return nil,e};if printedTask.MatchString(first){return nil,errors.New("Unknown printed task ID")}
 var existing string;e=s.DB.QueryRow("SELECT task_id FROM tasks WHERE block_id=?",b.ID).Scan(&existing);if e==nil{result[b.ID]=existing;continue};if e!=sql.ErrNoRows{return nil,e}
 tx,e:=s.DB.Begin();if e!=nil{return nil,e};var seq string;if e=tx.QueryRow("SELECT value FROM library_meta WHERE key='task_sequence'").Scan(&seq);e!=nil{tx.Rollback();return nil,e};n,e:=strconv.ParseInt(seq,10,64);if e!=nil{tx.Rollback();return nil,e};if n==int64(^uint64(0)>>1){tx.Rollback();return nil,errors.New("Task sequence exhausted")};id:=fmt.Sprintf("T%05d",n+1)
 if _,e=tx.Exec("UPDATE library_meta SET value=? WHERE key='task_sequence'",strconv.FormatInt(n+1,10));e==nil{_,e=tx.Exec("INSERT INTO tasks VALUES (?,?,'',NULL,'local')",b.ID,id)};if e==nil{_,e=tx.Exec("INSERT INTO task_data VALUES (?,?,0,?,0)",b.ID,b.Text,b.ParentID)};if e!=nil{tx.Rollback();return nil,e};if e=tx.Commit();e!=nil{return nil,e};result[b.ID]=id
 };return result,nil}
type taskRow struct{ID,Instance,Phase string;Remote sql.NullInt64}
func(s *Store)task(column,value string)(taskRow,error){var row taskRow;e:=s.DB.QueryRow("SELECT task_id,instance,remote_id,phase FROM tasks WHERE "+column+"=?",value).Scan(&row.ID,&row.Instance,&row.Remote,&row.Phase);return row,e}
func(s *Store)ExportTasks(ctx context.Context,p Proposal,c TaskConnector,instance string,project int)([]map[string]any,error){if _,e:=s.EnsureLocal(p);e!=nil{return nil,e};out:=[]map[string]any{};exported:=map[string]int64{}
 for _,b:=range p.Blocks{if b.Kind!="task"{continue};first:=firstWord(b.Text);mentioned,e:=s.task("task_id",first);if e==nil{if mentioned.Instance!=""&&mentioned.Instance!=instance{return nil,errors.New("Referenced task belongs to another instance")};if !mentioned.Remote.Valid||mentioned.Remote.Int64==0{return nil,errors.New("Referenced task must be exported from its original record first")};if _,e=s.DB.Exec("INSERT OR IGNORE INTO task_mentions VALUES (?,?)",b.ID,mentioned.ID);e!=nil{return nil,e};exported[b.ID]=mentioned.Remote.Int64;out=append(out,map[string]any{"task_id":mentioned.ID,"block_id":b.ID,"remote_id":mentioned.Remote.Int64});continue};if e!=sql.ErrNoRows{return nil,e}
 row,e:=s.task("block_id",b.ID);if e!=nil{return nil,e};if row.Instance!=""&&row.Instance!=instance{return nil,errors.New("Task belongs to another Vikunja instance")};if _,e=s.DB.Exec("UPDATE tasks SET instance=? WHERE block_id=?",instance,b.ID);e!=nil{return nil,e};if _,e=s.DB.Exec("UPDATE task_data SET project_id=? WHERE block_id=?",project,b.ID);e!=nil{return nil,e};var done int;var namespace string;if e=s.DB.QueryRow("SELECT done FROM task_data WHERE block_id=?",b.ID).Scan(&done);e!=nil{return nil,e};if e=s.DB.QueryRow("SELECT value FROM library_meta WHERE key='library_id'").Scan(&namespace);e!=nil{return nil,e};marker:="Paperwork origin: "+namespace+":"+row.ID;remote:=row.Remote.Int64
 if remote==0 {candidates,e:=c.Paginated(ctx,"/tasks",url.Values{"s":{row.ID}});if e!=nil{return nil,e};matches:=[]map[string]any{};for _,candidate:=range candidates{if strings.Contains(stringValue(candidate["description"]),marker){matches=append(matches,candidate)}};if len(matches)>1{return nil,errors.New("Duplicate remote identity; manual review required")};if len(matches)==1{remote=number(matches[0]["id"])}else{if row.Phase=="uncertain"{return nil,errors.New("Previous creation uncertain; verify remotely before retrying")};if _,e=s.DB.Exec("UPDATE tasks SET phase='uncertain' WHERE block_id=?",b.ID);e!=nil{return nil,e};created,e:=c.VK(ctx,"PUT",fmt.Sprintf("/projects/%d/tasks",project),map[string]any{"title":b.Text,"description":marker,"done":done!=0});if e!=nil{return nil,e};remote=number(created["id"])};if remote<=0{return nil,errors.New("Invalid remote task identity")};if _,e=s.DB.Exec("UPDATE tasks SET remote_id=?,phase='synced' WHERE block_id=?",remote,b.ID);e!=nil{return nil,e}}
 if done!=0||row.Phase=="pending-update"{current,e:=c.VK(ctx,"GET",fmt.Sprintf("/tasks/%d",remote),nil);if e!=nil{return nil,e};if boolValue(current["done"])!=(done!=0){current["done"]=done!=0;if _,e=c.VK(ctx,"POST",fmt.Sprintf("/tasks/%d",remote),current);e!=nil{return nil,e}};phase:="synced";if done!=0{phase="completed"};if _,e=s.DB.Exec("UPDATE tasks SET phase=? WHERE block_id=?",phase,b.ID);e!=nil{return nil,e}}
 exported[b.ID]=remote;if parent:=exported[str(b.ParentID)];parent!=0{current,e:=c.VK(ctx,"GET",fmt.Sprintf("/tasks/%d",parent),nil);if e!=nil{return nil,e};related,_:=object(current["related_tasks"])["subtask"].([]any);found:=false;for _,r:=range related{if number(object(r)["id"])==remote{found=true}};if !found{if _,e=c.VK(ctx,"PUT",fmt.Sprintf("/tasks/%d/relations",parent),map[string]any{"other_task_id":remote,"relation_kind":"subtask"});e!=nil{return nil,e}}};out=append(out,map[string]any{"task_id":row.ID,"block_id":b.ID,"remote_id":remote})
 };return out,nil
}
func(s *Store)ApplyUpdates(ctx context.Context,p Proposal,c TaskConnector,instance string)([]map[string]any,error){out:=[]map[string]any{};for _,b:=range p.Blocks{if b.Kind!="task-update"{continue};id:=firstWord(b.Text);row,e:=s.task("task_id",id);if e!=nil||(row.Instance!=""&&row.Instance!=instance){return nil,errors.New("Unknown task update or instance mismatch: "+id)};if _,e=s.DB.Exec("UPDATE task_data SET done=1 WHERE block_id=(SELECT block_id FROM tasks WHERE task_id=?)",id);e!=nil{return nil,e};result:=map[string]any{"task_id":id,"done":true};if !row.Remote.Valid||row.Remote.Int64==0{result["remote_pending"]=true;out=append(out,result);continue};task,e:=c.VK(ctx,"GET",fmt.Sprintf("/tasks/%d",row.Remote.Int64),nil);if e!=nil{return nil,e};if !boolValue(task["done"]){task["done"]=true;if _,e=c.VK(ctx,"POST",fmt.Sprintf("/tasks/%d",row.Remote.Int64),task);e!=nil{return nil,e}};if _,e=s.DB.Exec("UPDATE tasks SET phase='completed' WHERE task_id=?",id);e!=nil{return nil,e};out=append(out,result)};return out,nil}
